/* @autogenerated */
package net.civeira.phylax.feature.oauth.user.infrastructure;

import java.time.OffsetDateTime;
import java.util.Optional;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.crypto.SecretDigester;
import net.civeira.phylax.feature.access.userverificationcode.domain.UserVerificationCode;
import net.civeira.phylax.feature.access.userverificationcode.domain.UserVerificationCodeChangeSet;
import net.civeira.phylax.feature.access.userverificationcode.domain.UserVerificationCodePurposeOptions;
import net.civeira.phylax.feature.access.userverificationcode.domain.gateway.UserVerificationCodeCommandRepositoryGateway;
import net.civeira.phylax.feature.access.userverificationcode.domain.gateway.UserVerificationCodeFilter;
import net.civeira.phylax.feature.identity.user.domain.UserRef;

/**
 * Single-use codes sent by email, one per user and purpose: issuing a code replaces the pending one
 * of the same purpose, and a code is consumed (cleared) the first time it is accepted.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class VerificationCodeService {
  private final UserVerificationCodeCommandRepositoryGateway codes;
  private final SecretDigester secretDigester;

  public void issue(UserRef user, UserVerificationCodePurposeOptions purpose, String code,
      String returnUrl, OffsetDateTime expiresAt) {
    UserVerificationCode current =
        find(user, purpose).orElseGet(() -> codes.create(UserVerificationCode
            .create(new UserVerificationCodeChangeSet().newUid().user(user).purpose(purpose))));
    codes.update(current, current.generate(code, returnUrl, expiresAt));
  }

  /**
   * @return true when the code matches the pending one of that purpose and has not expired; it is
   *         then cleared, so the same code is never accepted twice.
   */
  public boolean consume(UserRef user, UserVerificationCodePurposeOptions purpose, String code) {
    if (null == code || code.isBlank()) {
      return false;
    }
    Optional<UserVerificationCode> find = find(user, purpose);
    if (find.isEmpty()) {
      return false;
    }
    UserVerificationCode current = find.get();
    boolean alive =
        current.getExpiresAt().map(at -> OffsetDateTime.now().isBefore(at)).orElse(false);
    if (!alive || !current.verify(secretDigester, code)) {
      return false;
    }
    codes.update(current, current.reset());
    return true;
  }

  /** Locks the only row of that user and purpose (unique index). */
  private Optional<UserVerificationCode> find(UserRef user,
      UserVerificationCodePurposeOptions purpose) {
    return codes.findForUpdate(UserVerificationCodeFilter.byUserAndPurpose(user, purpose));
  }
}
